import math
import re


def tokenise(text):
    return re.findall(r"[a-z]+", text.lower())


def idf(docs):
    n = len(docs)
    df = {}
    for d in docs:
        for w in set(tokenise(d)):
            df[w] = df.get(w, 0) + 1
    return {w: math.log((1 + n) / (1 + c)) + 1 for w, c in df.items()}

