import math


def tfidf_matrix(docs):
    w = idf(docs)
    vocab = sorted(w)
    col = {t: j for j, t in enumerate(vocab)}
    rows = []
    for d in docs:
        r = [0.0] * len(vocab)
        for t in tokenise(d):
            r[col[t]] += w[t]
        n = math.sqrt(sum(x * x for x in r))
        rows.append([x / n for x in r] if n > 0 else r)
    return vocab, rows

